CREATE TABLE IF NOT EXISTS npc_spawn_maker_random_positions (
    maker_tag        TEXT    NOT NULL
  , npc_template_id  INTEGER NOT NULL
  , total            INTEGER NOT NULL  CHECK(total >= 0)
  , respawn_duration INTEGER NOT NULL  CHECK(respawn_duration >= 0)
  , respawn_window   INTEGER           CHECK(respawn_window IS NULL OR respawn_window >= 1)
);

-- noinspection SqlWithoutWhere
DELETE FROM npc_spawn_maker_random_positions;
















